import semver

# Check R4: Bump methods
print("=== R4: Bump methods ===")
vi = semver.parse("1.2.3")
for method_name in ['bump_major', 'bump_minor', 'bump_patch', 'bump_prerelease', 'bump_build']:
    if hasattr(semver.VersionInfo, method_name):
        print(f"OK: {method_name} exists")
    else:
        print(f"MISSING: {method_name}")

# Check R5: Type conversion
print("\n=== R5: Type conversion ===")
vi = semver.VersionInfo(1, 2, 3, "alpha", "build1")
print(f"major type: {type(vi.major)}, minor type: {type(vi.minor)}, patch type: {type(vi.patch)}")
print(f"prerelease type: {type(vi.prerelease)}, build type: {type(vi.build)}")

# Test with non-string prerelease/build
try:
    vi2 = semver.VersionInfo(1, 2, 3, 99, 123)
    print(f"prerelease after int coercion: '{vi2.prerelease}' (type: {type(vi2.prerelease)})")
    print(f"build after int coercion: '{vi2.build}' (type: {type(vi2.build)})")
except Exception as e:
    print(f"Error: {e}")

# Check R6: CLI functions
print("\n=== R6: CLI functions ===")
for func_name in ['createparser', 'main', 'process']:
    if hasattr(semver, func_name):
        print(f"OK: {func_name} exists")
    else:
        print(f"MISSING: {func_name}")

# Check R7: Replace function
print("\n=== R7: Replace ===")
if hasattr(semver, 'replace'):
    print(f"OK: module-level replace exists")
else:
    print("MISSING: module-level replace")

if hasattr(semver.VersionInfo, 'replace'):
    print("OK: VersionInfo.replace method exists")
else:
    print("MISSING: VersionInfo.replace method")
